        <header><div><strong>Image editor</strong><small>Crop, mask, flip, and background changes are non-destructive.</small><small class="rd-modal__filename" title="${st(e.item.source.path)}">File: ${st(e.item.sourceFilename||ct(e.item.source.path))}</small></div><button type="button" data-action="cancel" aria-label="Close">×</button></header>
